"""
Qwen3-ASR (Transformers-native ``*-hf``).

Default timing: TEN VAD speech frames own the timeline (WhisperJAV-style
VAD-first). ForcedAligner is opt-in via ``timingAlignModel`` containing
``align`` / ``qwen3-forced-aligner``. Fallback when TEN is unavailable:
fixed windows + sentence/CPS cue distribution (no aligner VRAM).

HF load / generate / align live in ``qwen3_hf_*.py`` — keep this file as
orchestration only (no monolith growth).
"""

from __future__ import annotations

import logging
import re
import shutil
import sys
import tempfile
from pathlib import Path
from typing import Any, Callable

from ..download import is_model_installed, model_local_path
from ..progress import asr_local_from_timeline, format_mmss
from .qwen3_hf_align import align_transcript, attach_time_stamps
from .qwen3_hf_generate import generate_transcriptions, is_cuda_oom, result_text as _hf_result_text
from .qwen3_hf_model import clear_hf_model_cache, load_qwen3_hf_bundle

ProgressCb = Callable[[dict[str, Any]], None]
CueCb = Callable[[dict[str, Any]], None]
_log = logging.getLogger("transub_engine.asr.qwen3_asr")

_WINDOW_S = 90.0
_OVERLAP_S = 1.0
_MAX_CUE_S = 6.5
_GAP_BREAK_S = 0.4
_ALIGNER_ID = "qwen3-forced-aligner-0.6b"
_TARGET_CUE_CHARS = 28
_SENTENCE_SPLIT_RE = re.compile(r"(?<=[。！？!?．.｡…])")

# TEN frame grouping (aligned with anime-whisper defaults).
_VAD_CHUNK_THRESHOLD_S = 0.5
_VAD_MAX_GROUP_S = 5.0
_VAD_MIN_ISLAND_S = 0.22
_VAD_MERGE_GAP_S = 0.5
_QWEN_SR = 16000
# Outer island batches (1.7B / 0.6B); generate OOM half-splits inside qwen3_hf_generate.
_ISLAND_BATCH_1P7 = 8
_ISLAND_BATCH_DEFAULT = 16
_ISLAND_BATCH_CAP_1P7 = 16
_ISLAND_BATCH_CAP_DEFAULT = 32
# Process-session cap after CUDA OOM split (key: model|device|mode).
_SESSION_BATCH_CAP: dict[str, int] = {}
_ISLAND_BATCH_CTX: dict[str, Any] = {}
# Short VAD frames rarely need 512 tokens; cap cuts moan/hallucination loops.
_ISLAND_MAX_NEW_TOKENS = 192
# Same exception on every window → abort instead of grinding 90 silent failures.
_FAIL_FAST_SAME = 3

_LANG_MAP = {
    "ja": "Japanese",
    "jp": "Japanese",
    "zh": "Chinese",
    "cn": "Chinese",
    "en": "English",
    "yue": "Chinese",
    "ko": "Korean",
    "auto": None,
}


def clear_model_cache() -> int:
    n = clear_hf_model_cache()
    clear_island_batch_oom_caps()
    _ISLAND_BATCH_CTX.clear()
    try:
        import gc

        gc.collect()
    except Exception:
        pass
    try:
        import torch

        if torch.cuda.is_available():
            torch.cuda.empty_cache()
    except Exception:
        pass
    return n


def _probe_torch_cuda_import(timeout_sec: float = 90.0) -> bool:
    """True when a fresh process can import torch with CUDA libs within timeout.

    Windows LoadLibrary on cublas64_*.dll can hang forever (WinError 1114). Probing in a
    child process lets us kill the hang without freezing the serve GIL.
    """
    import os
    import subprocess

    from ..runtime_gpu import _torch_lib_dirs

    code = (
        "import torch\n"
        "print('ok', int(bool(torch.cuda.is_available())), flush=True)\n"
    )
    env = os.environ.copy()
    # Match serve preload: torch\\lib must beat nvidia-* or WinError 1114.
    # ROCm wheels also keep HIP DLLs beside torch/lib or in a sibling package.
    torch_libs = [d for d in _torch_lib_dirs() if d]
    try:
        from ..rocm_device import rocm_runtime_dirs

        torch_libs.extend(d for d in rocm_runtime_dirs() if d and d not in torch_libs)
    except Exception:
        pass
    if torch_libs:
        env["PATH"] = os.pathsep.join(torch_libs + [env.get("PATH", "")])
    try:
        proc = subprocess.Popen(
            [sys.executable, "-c", code],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            env=env,
        )
    except Exception as err:
        _log.warning("Qwen3-ASR: torch probe spawn failed: %s", err)
        return True  # fall through to in-process import
    try:
        out, err = proc.communicate(timeout=max(15.0, float(timeout_sec)))
    except subprocess.TimeoutExpired:
        try:
            proc.kill()
        except Exception:
            pass
        try:
            proc.wait(timeout=5)
        except Exception:
            pass
        _log.warning(
            "Qwen3-ASR: torch CUDA import probe timed out after %.0fs",
            timeout_sec,
        )
        return False
    if proc.returncode != 0:
        msg = (err or out or "").strip()
        _log.warning("Qwen3-ASR: torch probe failed (code=%s): %s", proc.returncode, msg[:400])
        return False
    return True


def _import_torch(*, prefer_cpu: bool = False):
    """Import torch; recover from Windows cuBLAS WinError 999/1114 after PATH inject.

    Do **not** sticky-set CUDA_VISIBLE_DEVICES="" on conflict: that poisons the whole
    engine process for later batch items (GPU→CPU forever until restart). Prefer
    preload recovery; if still broken, raise so the job can fail/retry after release.
    Explicit prefer_cpu may hide devices for this import only when torch is not yet loaded.
    """
    import os

    from ..device import (
        clear_partial_torch_modules,
        format_torch_cuda_load_failure,
        is_torch_c_extension_loaded,
        is_torch_cublas_load_conflict,
        is_torch_fully_imported,
        is_torch_reimport_poison_error,
        is_torch_reimport_poisoned,
        mark_torch_import_failed_after_native,
        mark_torch_import_ok,
        torch_reimport_poison_message,
    )

    if is_torch_reimport_poisoned():
        raise RuntimeError(torch_reimport_poison_message())

    if is_torch_fully_imported():
        import torch

        mark_torch_import_ok()
        return torch

    prev_cvd = os.environ.get("CUDA_VISIBLE_DEVICES")
    if prefer_cpu:
        # CUDA wheel still loads cublas on import — hide devices only for this attempt
        # and restore so a later process restart / fresh import can see the GPU again.
        os.environ["CUDA_VISIBLE_DEVICES"] = ""

    try:
        import torch

        mark_torch_import_ok()
        return torch
    except OSError as err:
        if not is_torch_cublas_load_conflict(err):
            if is_torch_c_extension_loaded() or is_torch_reimport_poison_error(err):
                mark_torch_import_failed_after_native()
            raise
        if is_torch_c_extension_loaded():
            mark_torch_import_failed_after_native()
            raise RuntimeError(format_torch_cuda_load_failure(err)) from err
        clear_partial_torch_modules()
        # Retry with torch\\lib first (same as serve preload).
        try:
            from ..runtime_gpu import preload_torch_cuda_dlls

            pre = preload_torch_cuda_dlls()
            if pre.get("ok"):
                import torch

                mark_torch_import_ok()
                return torch
        except Exception as pre_err:
            if is_torch_reimport_poison_error(pre_err) or is_torch_c_extension_loaded():
                mark_torch_import_failed_after_native()
            else:
                clear_partial_torch_modules()
        # Do not import under sticky CUDA_VISIBLE_DEVICES="" — that would bind the
        # process to CPU for all subsequent multitask jobs.
        raise RuntimeError(format_torch_cuda_load_failure(err)) from err
    except Exception as err:
        if is_torch_reimport_poison_error(err) or is_torch_c_extension_loaded():
            mark_torch_import_failed_after_native()
            raise RuntimeError(format_torch_cuda_load_failure(err)) from err
        raise
    finally:
        if prefer_cpu:
            if prev_cvd is None:
                os.environ.pop("CUDA_VISIBLE_DEVICES", None)
            else:
                os.environ["CUDA_VISIBLE_DEVICES"] = prev_cvd


def _map_language(language: str | None) -> str | None:
    raw = str(language or "auto").strip().lower()
    if not raw or raw == "auto":
        return None
    if raw in _LANG_MAP:
        return _LANG_MAP[raw]
    # Already a Qwen language name?
    if raw[:1].isupper() or " " in raw:
        return str(language).strip()
    return None


def _device_map(device: str, *, torch_mod: Any | None = None) -> str:
    from ..device import is_torch_cublas_load_conflict, torch_cuda_suitable_for_gpu

    d = str(device or "auto").strip().lower()
    if d == "cpu":
        return "cpu"
    try:
        torch = torch_mod or _import_torch()

        if torch.cuda.is_available() and d in ("auto", "cuda"):
            ok, note = torch_cuda_suitable_for_gpu()
            if ok:
                return "cuda:0"
            if note:
                _log.warning("Qwen3-ASR: %s — falling back to CPU", note)
    except OSError as err:
        if is_torch_cublas_load_conflict(err):
            _log.warning("Qwen3-ASR: torch CUDA cuBLAS conflict — falling back to CPU")
    except RuntimeError as err:
        if is_torch_cublas_load_conflict(err):
            _log.warning("Qwen3-ASR: %s — falling back to CPU", err)
    except Exception:
        pass
    return "cpu"


def wants_forced_aligner(timing_align_model: str | None) -> bool:
    """True when job explicitly requests Qwen ForcedAligner word timestamps."""
    raw = str(timing_align_model or "").strip().lower().replace("_", "-")
    if not raw:
        return False
    if raw in (
        "ten",
        "ten-vad",
        "vad",
        "auto",
        "firered",
        "firered-vad",
        "fire-red",
        "fireredvad",
        "off",
        "rate",
        "none",
        "cps",
    ):
        return False
    if raw == _ALIGNER_ID or raw.startswith("qwen3-forced"):
        return True
    if "align" in raw:
        return True
    return False


def _island_vad_backend(timing_align_model: str | None) -> str | None:
    """``ten`` | ``firered`` | ``None`` (fixed windows)."""
    if timing_align_model is None:
        return "ten"
    raw = str(timing_align_model).strip().lower().replace("_", "-")
    if raw == "":
        return None
    if wants_forced_aligner(timing_align_model):
        return None
    if raw in ("firered", "firered-vad", "fire-red", "fireredvad"):
        return "firered"
    if raw in ("ten", "ten-vad", "vad", "auto"):
        return "ten"
    return "ten"


def normalize_qwen_batch_mode(raw: str | None) -> str:
    """``auto`` | ``conservative`` | ``aggressive``."""
    v = str(raw or "auto").strip().lower()
    if v in ("conservative", "safe", "low"):
        return "conservative"
    if v in ("aggressive", "fast", "high"):
        return "aggressive"
    return "auto"


def _is_17b_asr_model(asr_model: str | None) -> bool:
    return "1.7" in str(asr_model or "").lower()


def _legacy_island_batch_size(asr_model: str | None) -> int:
    if _is_17b_asr_model(asr_model):
        return _ISLAND_BATCH_1P7
    return _ISLAND_BATCH_DEFAULT


def _probe_gpu_free_mib() -> tuple[int | None, int | None]:
    """Best-effort (free_mib, total_mib). Avoid importing torch unless already loaded."""
    import sys

    if "torch" in sys.modules:
        try:
            torch = sys.modules["torch"]
            if torch.cuda.is_available():
                free_b, total_b = torch.cuda.mem_get_info(0)
                return int(free_b // (1024 * 1024)), int(total_b // (1024 * 1024))
        except Exception:
            pass
    try:
        from ..device import detect_device

        total = int(detect_device().get("vramMb") or 0)
        if total > 0:
            return None, total
    except Exception:
        pass
    return None, None


def _resolve_vram_mib(
    *,
    job_gpu_free_mib: int | None = None,
    job_gpu_total_mib: int | None = None,
) -> tuple[int | None, int | None]:
    """Prefer shell pre-job sample; fall back to torch/detect_device probe."""
    free_mib, total_mib = _probe_gpu_free_mib()
    try:
        jf = int(job_gpu_free_mib) if job_gpu_free_mib is not None else None
        if jf is not None and jf > 0:
            free_mib = jf
    except (TypeError, ValueError):
        pass
    try:
        jt = int(job_gpu_total_mib) if job_gpu_total_mib is not None else None
        if jt is not None and jt > 0:
            total_mib = jt
    except (TypeError, ValueError):
        pass
    return free_mib, total_mib


def _asr_runs_on_cuda(device: str) -> bool:
    d = str(device or "auto").strip().lower()
    if d == "cpu":
        return False
    if d == "cuda":
        return True
    try:
        from ..device import detect_device

        info = detect_device()
        return bool(info.get("hasCuda") or info.get("hasRocm"))
    except Exception:
        return False


def _auto_batch_from_vram(
    *,
    is_17b: bool,
    free_mib: int | None,
    total_mib: int | None,
    headroom_frac: float = 0.55,
) -> int:
    avail = int(free_mib) if free_mib and free_mib > 0 else 0
    if avail <= 0 and total_mib and total_mib > 0:
        frac = max(0.35, min(0.90, float(headroom_frac)))
        avail = int(total_mib * frac)
    if avail <= 0:
        return _legacy_island_batch_size("1.7b" if is_17b else "0.6b")
    if is_17b:
        if avail >= 14000:
            return 16
        if avail >= 10000:
            return 12
        if avail >= 7000:
            return 8
        if avail >= 5000:
            return 6
        return 4
    if avail >= 12000:
        return 32
    if avail >= 8000:
        return 24
    if avail >= 5000:
        return 16
    if avail >= 3000:
        return 12
    return 8


def _aggressive_batch_from_vram(
    *,
    is_17b: bool,
    free_mib: int | None,
    total_mib: int | None,
    auto_n: int,
    base: int,
    cap: int,
) -> int:
    """Push toward cap using optimistic headroom; OOM split still applies downstream."""
    opt = max(
        auto_n,
        _auto_batch_from_vram(
            is_17b=is_17b,
            free_mib=free_mib,
            total_mib=total_mib,
            headroom_frac=0.80,
        ),
    )
    total = int(total_mib or 0)
    if is_17b:
        if total >= 16000:
            opt = max(opt, 16)
        elif total >= 12000:
            opt = max(opt, 12)
        elif total >= 10000:
            opt = max(opt, 10)
    else:
        if total >= 12000:
            opt = max(opt, 32)
        elif total >= 8000:
            opt = max(opt, 24)
        elif total >= 6000:
            opt = max(opt, 20)
    return max(base, min(cap, opt))


def _batch_session_key(asr_model: str | None, device: str, batch_mode: str | None) -> str:
    return (
        f"{str(asr_model or '').strip()}|"
        f"{str(device or 'auto').strip().lower()}|"
        f"{normalize_qwen_batch_mode(batch_mode)}"
    )


def note_island_batch_oom_cap(
    asr_model: str | None,
    device: str,
    batch_mode: str | None,
    attempted_n: int,
) -> None:
    key = _batch_session_key(asr_model, device, batch_mode)
    prev = _SESSION_BATCH_CAP.get(key, 999)
    new_cap = max(1, int(attempted_n) // 2)
    _SESSION_BATCH_CAP[key] = min(prev, new_cap)
    _log.warning(
        "Qwen island batch OOM cap: %s -> %d (attempted %d)",
        key,
        _SESSION_BATCH_CAP[key],
        attempted_n,
    )


def clear_island_batch_oom_caps() -> int:
    n = len(_SESSION_BATCH_CAP)
    _SESSION_BATCH_CAP.clear()
    return n


def get_island_batch_oom_cap(
    asr_model: str | None,
    device: str,
    batch_mode: str | None,
) -> int | None:
    return _SESSION_BATCH_CAP.get(_batch_session_key(asr_model, device, batch_mode))


def _set_island_batch_ctx(**kwargs: Any) -> None:
    _ISLAND_BATCH_CTX.clear()
    _ISLAND_BATCH_CTX.update(kwargs)


def _effective_batch_mode(
    batch_mode: str | None,
    perf_profile: str | None = None,
) -> str:
    mode = normalize_qwen_batch_mode(batch_mode)
    if str(perf_profile or "").strip().lower() == "speed":
        return "conservative"
    return mode


def resolve_island_batch_size(
    asr_model: str | None,
    *,
    batch_mode: str | None = "auto",
    device: str = "auto",
    perf_profile: str | None = None,
    job_gpu_free_mib: int | None = None,
    job_gpu_total_mib: int | None = None,
) -> int:
    """
    TEN/FireRed island batch count for ``model.transcribe([...])``.

    conservative: never above legacy 8/16; may shrink on tight VRAM.
    auto: VRAM-scaled (default).
    aggressive: up to 16/32 when VRAM allows.
    """
    mode = _effective_batch_mode(batch_mode, perf_profile)
    is_17b = _is_17b_asr_model(asr_model)
    base = _ISLAND_BATCH_1P7 if is_17b else _ISLAND_BATCH_DEFAULT
    cap = _ISLAND_BATCH_CAP_1P7 if is_17b else _ISLAND_BATCH_CAP_DEFAULT
    if not _asr_runs_on_cuda(device):
        return max(1, min(2, base // 4 or 1))
    free_mib, total_mib = _resolve_vram_mib(
        job_gpu_free_mib=job_gpu_free_mib,
        job_gpu_total_mib=job_gpu_total_mib,
    )
    auto_n = max(1, min(cap, _auto_batch_from_vram(
        is_17b=is_17b,
        free_mib=free_mib,
        total_mib=total_mib,
    )))
    if mode == "conservative":
        n = max(1, min(base, auto_n))
    elif mode == "aggressive":
        n = _aggressive_batch_from_vram(
            is_17b=is_17b,
            free_mib=free_mib,
            total_mib=total_mib,
            auto_n=auto_n,
            base=base,
            cap=cap,
        )
    else:
        n = auto_n
    oom_cap = get_island_batch_oom_cap(asr_model, device, mode)
    if oom_cap is not None:
        n = min(n, max(1, int(oom_cap)))
    return max(1, n)


def _island_batch_size(asr_model: str | None) -> int:
    """Backward-compatible default (conservative legacy caps)."""
    return _legacy_island_batch_size(asr_model)


def _enable_cuda_fast_matmul() -> None:
    try:
        torch = _import_torch()

        if torch.cuda.is_available():
            torch.backends.cuda.matmul.allow_tf32 = True
            torch.backends.cudnn.allow_tf32 = True
    except Exception:
        pass


def _get_asr_model(asr_dir: Path, aligner_dir: Path | None, device: str) -> Any:
    """Resolve device then load Transformers-native bundle."""
    torch = _import_torch()
    resolved = _device_map(device, torch_mod=torch)
    if str(resolved).startswith("cuda"):
        _enable_cuda_fast_matmul()
    return load_qwen3_hf_bundle(
        asr_dir,
        device=resolved,
        aligner_dir=aligner_dir,
        torch_mod=torch,
    )


def _probe_duration_s(media_path: str) -> float:
    try:
        from .whisper_fw import _probe_duration_s as probe

        return float(probe(media_path) or 0)
    except Exception:
        return 0.0


def _windows(duration_s: float) -> list[tuple[float, float]]:
    if duration_s <= _WINDOW_S + 1.0:
        return [(0.0, max(duration_s, 0.1))]
    out: list[tuple[float, float]] = []
    cursor = 0.0
    step = max(10.0, _WINDOW_S - _OVERLAP_S)
    while cursor < duration_s - 0.05:
        end = min(duration_s, cursor + _WINDOW_S)
        out.append((cursor, end))
        if end >= duration_s - 0.05:
            break
        cursor += step
    return out or [(0.0, max(duration_s, 0.1))]


def _windows_in_span(start_s: float, end_s: float) -> list[tuple[float, float]]:
    """Fixed windows covering ``[start_s, end_s)`` (hole-fill helper)."""
    lo = max(0.0, float(start_s))
    hi = max(lo + 0.1, float(end_s))
    span = hi - lo
    if span <= _WINDOW_S + 1.0:
        return [(lo, hi)]
    return [(lo + s, min(hi, lo + e)) for s, e in _windows(span)]


def _vad_hole_fill_windows(
    clips: list[dict[str, float]],
    *,
    duration_s: float,
    min_hole_s: float = 90.0,
) -> list[tuple[float, float]]:
    """Fixed windows for ≥min_hole_s gaps between VAD islands (and head/tail)."""
    dur = max(0.0, float(duration_s or 0))
    gap_lim = max(30.0, float(min_hole_s or 90.0))
    if dur <= 0:
        return []
    ordered = sorted(
        (
            {
                "start": float(c.get("start") or 0),
                "end": float(c.get("end") or 0),
            }
            for c in clips
            if float(c.get("end") or 0) > float(c.get("start") or 0)
        ),
        key=lambda c: c["start"],
    )
    gaps: list[tuple[float, float]] = []
    cursor = 0.0
    for c in ordered:
        gs, ge = cursor, float(c["start"])
        if ge - gs >= gap_lim:
            gaps.append((gs, ge))
        cursor = max(cursor, float(c["end"]))
    if dur - cursor >= gap_lim:
        gaps.append((cursor, dur))
    out: list[tuple[float, float]] = []
    for gs, ge in gaps:
        out.extend(_windows_in_span(gs, ge))
    return out


def _split_sentences(text: str) -> list[str]:
    raw = str(text or "").strip()
    if not raw:
        return []
    parts = [p.strip() for p in _SENTENCE_SPLIT_RE.split(raw) if p and p.strip()]
    if len(parts) <= 1 and len(raw) > _TARGET_CUE_CHARS * 2:
        chunk = _TARGET_CUE_CHARS
        parts = [raw[i : i + chunk].strip() for i in range(0, len(raw), chunk)]
        parts = [p for p in parts if p]
    return parts or [raw]


def _distribute_text_cues(
    text: str,
    *,
    start: float,
    end: float,
) -> list[dict[str, Any]]:
    """Paint ASR text onto a VAD/window span with sentence/CPS sub-cues."""
    try:
        from .whisper_fw import split_frame_text_to_cues

        cues = split_frame_text_to_cues(text, float(start), float(end))
        if cues:
            return cues
    except Exception:
        pass
    parts = _split_sentences(text)
    if not parts:
        return []
    span = max(0.35, float(end) - float(start))
    weights = [max(1, len(p)) for p in parts]
    total_w = float(sum(weights))
    cues: list[dict[str, Any]] = []
    cursor = float(start)
    for i, (part, w) in enumerate(zip(parts, weights)):
        frac = w / total_w
        dur = span * frac
        if i == len(parts) - 1:
            cue_end = float(end)
        else:
            cue_end = min(float(end), cursor + max(0.35, dur))
        cue_end = max(cue_end, cursor + 0.25)
        cues.append(
            {
                "start": cursor,
                "end": min(cue_end, cursor + _MAX_CUE_S * 2),
                "text": part,
            }
        )
        cursor = cue_end
    return cues


def _ts_items_to_cues(time_stamps: Any, *, offset_s: float = 0.0) -> list[dict[str, Any]]:
    """Convert Qwen ForcedAligner timestamp list into subtitle cues."""
    if not time_stamps:
        return []
    items: list[tuple[float, float, str]] = []
    for ts in time_stamps:
        text = str(getattr(ts, "text", None) or getattr(ts, "word", None) or "").strip()
        if not text:
            continue
        start = float(getattr(ts, "start_time", None) or getattr(ts, "start", 0) or 0)
        end = float(getattr(ts, "end_time", None) or getattr(ts, "end", start) or start)
        items.append((start + offset_s, max(end, start) + offset_s, text))
    if not items:
        return []

    cues: list[dict[str, Any]] = []
    buf: list[str] = []
    buf_start = items[0][0]
    prev_end = items[0][1]
    for start, end, text in items:
        gap = start - prev_end
        flush = False
        if buf and gap >= _GAP_BREAK_S:
            flush = True
        joined = "".join(buf)
        if buf and len(joined) >= 28:
            flush = True
        if buf and joined and joined[-1] in "。！？!?．.｡":
            flush = True
        if flush:
            cues.append(
                {
                    "start": buf_start,
                    "end": min(max(prev_end, buf_start + 0.25), buf_start + _MAX_CUE_S),
                    "text": joined.strip(),
                }
            )
            buf = []
            buf_start = start
        buf.append(text)
        prev_end = max(prev_end, end)
    if buf:
        cues.append(
            {
                "start": buf_start,
                "end": min(max(prev_end, buf_start + 0.25), buf_start + _MAX_CUE_S),
                "text": "".join(buf).strip(),
            }
        )
    return [c for c in cues if str(c.get("text") or "").strip()]


def _result_text(result: Any) -> str:
    return _hf_result_text(result)


def _result_to_cues_aligned(result: Any, *, offset_s: float, span_s: float) -> list[dict[str, Any]]:
    text = _result_text(result)
    stamps = getattr(result, "time_stamps", None)
    if stamps:
        cues = _ts_items_to_cues(stamps, offset_s=offset_s)
        if cues:
            return cues
    if not text:
        return []
    return _distribute_text_cues(text, start=offset_s, end=offset_s + max(0.35, float(span_s) * 0.95))


def _is_cuda_oom(err: BaseException) -> bool:
    return is_cuda_oom(err)


def _is_systemic_qwen_error(err: BaseException) -> bool:
    """Errors that will not recover on the next window/batch."""
    if _is_cuda_oom(err):
        return True
    msg = str(err or "").lower()
    needles = (
        "numba needs numpy",
        "no module named",
        "cannot import",
        "dll load failed",
        "cuda error",
        "no kernel image",
        "cudaerrornokernelimagefordevice",
        "invalid device",
        "device-side assert",
        "cudnn",
        "cublas",
        "winerror 999",
        "expected all tensors to be on the same device",
        "not enough memory",
        "paging file",
    )
    return any(n in msg for n in needles)


def _qwen_error_text(err: BaseException | None) -> str:
    if err is None:
        return "unknown error"
    msg = str(err).strip() or type(err).__name__
    if _is_cuda_oom(err):
        return (
            f"{msg}。显存不足：请关闭占用显卡的本地大模型后重试，"
            "或改用 Qwen3-ASR 0.6B / Anime Whisper。"
        )
    low = msg.lower()
    if "no kernel image" in low or "cudaerrornokernelimagefordevice" in low:
        return (
            f"{msg}。本机显卡（如 RTX 50 系 Blackwell）需要 CUDA 12.8+ / 13.x 版 PyTorch（cu128 或 cu130），"
            "请在设置中「补齐 CUDA PyTorch」或手动安装匹配版本的 torch / torchaudio；"
            "也可暂时改用 CPU 或 anime-whisper ASR。"
        )
    return msg[:500]


def _qwen_fail_fast(
    *,
    err: BaseException,
    first_err: BaseException | None,
    same_streak: int,
) -> bool:
    if _is_systemic_qwen_error(err) or _is_systemic_qwen_error(first_err or err):
        return True
    return same_streak >= _FAIL_FAST_SAME


def _empty_cuda_cache() -> None:
    try:
        import gc

        gc.collect()
    except Exception:
        pass
    try:
        import torch

        if torch.cuda.is_available():
            torch.cuda.empty_cache()
    except Exception:
        pass


def _transcribe_audio_list(
    bundle: Any,
    audios: list[Any],
    lang: str | None,
    *,
    want_ts: bool,
    max_new_tokens: int | None = None,
) -> list[Any]:
    """One HF generate pass over a list (paths or (ndarray, sr) tuples)."""
    if not audios:
        return []
    tok = int(max_new_tokens) if max_new_tokens else (
        _ISLAND_MAX_NEW_TOKENS if not want_ts else 512
    )

    def _on_oom(batch_len: int) -> None:
        ctx = _ISLAND_BATCH_CTX
        if ctx:
            note_island_batch_oom_cap(
                str(ctx.get("asr_model") or ""),
                str(ctx.get("device") or "auto"),
                ctx.get("batch_mode"),
                int(batch_len),
            )

    results = generate_transcriptions(
        bundle,
        audios,
        lang,
        max_new_tokens=tok,
        on_oom_cap=_on_oom,
    )
    if want_ts and getattr(bundle, "has_aligner", False):
        aligned: list[Any] = []
        for audio, result in zip(audios, results):
            text = _result_text(result)
            path = audio if isinstance(audio, (str, Path)) else audio
            # PCM tuples: write is handled inside generate; re-align needs a path.
            if isinstance(path, tuple):
                aligned.append(result)
                continue
            stamps = align_transcript(
                bundle,
                audio=str(path),
                transcript=text,
                language=lang or getattr(result, "language", None),
            )
            aligned.append(attach_time_stamps(result, stamps) if stamps else result)
        return aligned
    return results


def _transcribe_wav(bundle: Any, wav: str, lang: str | None, *, want_ts: bool) -> Any:
    results = _transcribe_audio_list(bundle, [str(wav)], lang, want_ts=want_ts)
    return results[0] if results else None


def _pcm_tuple_for_span(
    audio_f32: Any,
    start: float,
    end: float,
) -> tuple[Any, int] | None:
    if audio_f32 is None:
        return None
    try:
        from ..vad.ten_vad_seg import slice_pcm_f32

        clip = slice_pcm_f32(audio_f32, start, end, sample_rate=_QWEN_SR)
        if clip.size < int(0.05 * _QWEN_SR):
            return None
        return (clip, _QWEN_SR)
    except Exception:
        return None


def _dedupe_overlap_cues(all_cues: list[dict[str, Any]]) -> list[dict[str, Any]]:
    all_cues.sort(key=lambda c: (float(c.get("start") or 0), float(c.get("end") or 0)))
    cleaned: list[dict[str, Any]] = []
    for cue in all_cues:
        text = str(cue.get("text") or "").strip()
        if not text:
            continue
        item = dict(cue)
        if cleaned and float(item["start"]) < float(cleaned[-1]["end"]) - 0.05:
            item["start"] = float(cleaned[-1]["end"])
            if float(item["end"]) <= float(item["start"]):
                item["end"] = float(item["start"]) + 0.25
        cleaned.append(item)
    return cleaned


def _qwen_island_vad_transcribe(
    *,
    media_path: str,
    model: Any,
    lang: str | None,
    duration_s: float,
    vad_backend: str = "ten",
    device: str = "auto",
    asr_model: str = "",
    qwen_batch_mode: str | None = "auto",
    perf_profile: str | None = None,
    job_gpu_free_mib: int | None = None,
    job_gpu_total_mib: int | None = None,
    island_batch_n: int | None = None,
    on_progress: ProgressCb | None,
    on_cue: CueCb | None,
    should_cancel: Callable[[], bool] | None,
) -> list[dict[str, Any]] | None:
    """TEN or FireRed VAD frames → Qwen text; VAD owns timeline."""
    from .whisper_fw import group_vad_intervals

    media_name = Path(media_path).name
    backend = str(vad_backend or "ten").strip().lower()
    intervals: list[tuple[float, float]] | None = None
    audio_f32: Any = None
    label = "TEN"

    if backend == "firered":
        label = "FireRed"
        try:
            from ..runtime_extras import ensure_extras_for_models
            from ..vad.firered_vad_seg import (
                collect_firered_vad_intervals_with_audio,
                firered_vad_available,
                firered_weights_dir,
            )

            ensure_extras_for_models(["firered-vad"], force=False, on_progress=on_progress)
            if not firered_vad_available() or firered_weights_dir() is None:
                _log.info(
                    "Qwen FireRed path skipped: package/weights missing | %s -> TEN/windowed",
                    media_name,
                )
                backend = "ten"
            else:
                intervals, audio_f32 = collect_firered_vad_intervals_with_audio(
                    media_path,
                    max_media_s=duration_s if duration_s > 0 else None,
                    merge_gap_s=_VAD_MERGE_GAP_S,
                    device=device,
                )
        except Exception as err:
            _log.warning(
                "Qwen FireRed VAD collect failed for %s: %s -> TEN/windowed",
                media_name,
                err,
            )
            backend = "ten"
            intervals = None
            audio_f32 = None

    if backend == "ten":
        label = "TEN"
        from ..vad.ten_vad_seg import collect_ten_vad_intervals_with_audio, ten_vad_available

        if not ten_vad_available():
            _log.info(
                "Qwen TEN path skipped: ten-vad not installed | %s -> windowed fallback",
                media_name,
            )
            return None
        try:
            intervals, audio_f32 = collect_ten_vad_intervals_with_audio(
                media_path,
                max_media_s=duration_s if duration_s > 0 else None,
                merge_gap_s=_VAD_MERGE_GAP_S,
            )
        except Exception as err:
            _log.warning(
                "Qwen TEN VAD collect failed for %s: %s -> windowed fallback",
                media_name,
                err,
            )
            return None

    if not intervals:
        _log.info("Qwen %s VAD found no speech on %s; windowed fallback", label, media_name)
        return None

    # Same sparse policy as WhisperSeg for *empty* VAD. Large holes alone used
    # to discard all islands → full 90s windows; on soft AV Qwen often returns
    # only "…" and drops intro dialogue TEN already found (NAAC-076). Hybrid:
    # keep islands + fill ≥90s gaps.
    hole_fill_windows: list[tuple[float, float]] = []
    try:
        from ..vad.whisperseg import classify_vad_coverage

        cov_clips = [
            {"start": float(s), "end": float(e)}
            for s, e in intervals
            if float(e) > float(s)
        ]
        coverage = classify_vad_coverage(cov_clips, duration_s=duration_s)
        if coverage == "empty":
            spoken = sum(max(0.0, c["end"] - c["start"]) for c in cov_clips)
            ratio = (spoken / duration_s) if duration_s > 0 else 0.0
            _log.info(
                "Qwen %s VAD too sparse on %s (islands=%d spoken=%.1f%%) -> windowed fallback",
                label,
                media_name,
                len(cov_clips),
                ratio * 100.0,
            )
            if on_progress:
                on_progress(
                    {
                        "stage": "vad_failover",
                        "percent": 14,
                        "detail": (
                            f"{label} 过稀（人声约 {ratio:.1%}）· 回退定长开窗"
                            if cov_clips
                            else f"{label} 无岛 · 回退定长开窗"
                        ),
                    }
                )
            return None
        if coverage == "holes":
            hole_fill_windows = _vad_hole_fill_windows(
                cov_clips, duration_s=duration_s, min_hole_s=90.0
            )
            spoken = sum(max(0.0, c["end"] - c["start"]) for c in cov_clips)
            ratio = (spoken / duration_s) if duration_s > 0 else 0.0
            _log.info(
                "Qwen %s hybrid on %s: keep islands=%d spoken=%.1f%% + hole_windows=%d",
                label,
                media_name,
                len(cov_clips),
                ratio * 100.0,
                len(hole_fill_windows),
            )
            if on_progress:
                on_progress(
                    {
                        "stage": "vad",
                        "percent": 14,
                        "detail": (
                            f"{label} 岛保留 + 空洞补窗 "
                            f"{len(hole_fill_windows)}（人声约 {ratio:.1%}）"
                        ),
                    }
                )
    except Exception as err:
        _log.warning("Qwen %s sparse coverage check failed: %s", label, err)

    pieces = group_vad_intervals(
        intervals,
        chunk_threshold_s=_VAD_CHUNK_THRESHOLD_S,
        max_group_duration_s=_VAD_MAX_GROUP_S,
    )
    if not pieces and not hole_fill_windows:
        return None

    frames: list[tuple[float, float, Any]] = []
    for start, end in pieces:
        if max(0.0, end - start) < _VAD_MIN_ISLAND_S:
            continue
        frames.append((start, end, _pcm_tuple_for_span(audio_f32, start, end)))
    for start, end in hole_fill_windows:
        if max(0.0, end - start) < _VAD_MIN_ISLAND_S:
            continue
        frames.append((start, end, _pcm_tuple_for_span(audio_f32, start, end)))
    if not frames:
        return None

    batch_n = max(
        1,
        int(island_batch_n)
        if island_batch_n is not None and int(island_batch_n) > 0
        else resolve_island_batch_size(
            asr_model,
            batch_mode=qwen_batch_mode,
            device=device,
            perf_profile=perf_profile,
            job_gpu_free_mib=job_gpu_free_mib,
            job_gpu_total_mib=job_gpu_total_mib,
        ),
    )
    effective_mode = _effective_batch_mode(qwen_batch_mode, perf_profile)
    batch_label = effective_mode
    _set_island_batch_ctx(
        asr_model=asr_model,
        device=device,
        batch_mode=effective_mode,
    )
    pcm_n = sum(1 for _s, _e, item in frames if item is not None)
    _log.info(
        "Qwen %s frames: %s | islands=%d -> frames=%d | pcm=%d/%d | batch=%d (%s) | first=%.1f-%.1fs",
        label,
        media_name,
        len(intervals),
        len(frames),
        pcm_n,
        len(frames),
        batch_n,
        batch_label,
        frames[0][0],
        frames[0][1],
    )

    work: Path | None = None
    all_cues: list[dict[str, Any]] = []
    fail_count = 0
    ffmpeg_n = 0
    first_err: BaseException | None = None
    last_key = ""
    same_streak = 0
    try:
        if on_progress:
            on_progress(
                {
                    "stage": "transcribe",
                    "percent": 12,
                    "detail": f"{label} 人声帧 {len(frames)} 段 · 批 {batch_n} ({batch_label}) | Qwen3-ASR",
                    "processedSec": 0.0,
                    "mediaDurationSec": duration_s if duration_s > 0 else None,
                }
            )
        idx = 0
        while idx < len(frames):
            if should_cancel and should_cancel():
                raise RuntimeError("cancelled")
            oom_cap = get_island_batch_oom_cap(asr_model, device, effective_mode)
            cur_batch = batch_n
            if oom_cap is not None:
                cur_batch = min(cur_batch, max(1, int(oom_cap)))
            chunk = frames[idx : idx + cur_batch]
            audios: list[Any] = []
            for j, (start, end, item) in enumerate(chunk):
                if item is not None:
                    audios.append(item)
                    continue
                from ..audio.preprocess import trim_media_window

                if work is None:
                    work = Path(tempfile.mkdtemp(prefix="qwen3_vad_"))
                wav = trim_media_window(
                    media_path,
                    start_sec=start,
                    end_sec=end,
                    out_dir=work / f"f{idx + j:04d}",
                )
                audios.append(str(wav))
                ffmpeg_n += 1
            start0 = float(chunk[0][0])
            if on_progress:
                local = asr_local_from_timeline(
                    processed_s=start0,
                    duration_s=duration_s,
                    start=12.0,
                    end=92.0,
                )
                on_progress(
                    {
                        "stage": "transcribe",
                        "percent": int(local),
                        "detail": (
                            f"{label} {idx + 1}–{idx + len(chunk)}/{len(frames)}"
                            f" · {format_mmss(start0)}"
                        ),
                        "processedSec": start0,
                        "mediaDurationSec": duration_s,
                    }
                )
            try:
                results = _transcribe_audio_list(
                    model,
                    audios,
                    lang,
                    want_ts=False,
                    max_new_tokens=_ISLAND_MAX_NEW_TOKENS,
                )
            except Exception as err:
                fail_count += len(chunk)
                if first_err is None:
                    first_err = err
                key = str(err)[:240]
                same_streak = same_streak + 1 if key == last_key else 1
                last_key = key
                _log.warning(
                    "Qwen %s batch %d–%d failed: %s",
                    label,
                    idx + 1,
                    idx + len(chunk),
                    err,
                )
                if _qwen_fail_fast(err=err, first_err=first_err, same_streak=same_streak):
                    raise RuntimeError(
                        f"Qwen3-ASR {label} failed {fail_count}/{len(frames)} frames "
                        f"({media_name}): {_qwen_error_text(first_err)}"
                    ) from err
                idx += len(chunk)
                continue
            for (start, end, _item), result in zip(chunk, results):
                text = _result_text(result)
                if not text:
                    continue
                part = _distribute_text_cues(text, start=start, end=end)
                for cue in part:
                    if on_cue:
                        on_cue(cue)
                    all_cues.append(cue)
            idx += len(chunk)
    finally:
        if work is not None:
            shutil.rmtree(work, ignore_errors=True)

    if ffmpeg_n:
        _log.info(
            "Qwen %s used ffmpeg trim for %d/%d frames on %s",
            label,
            ffmpeg_n,
            len(frames),
            media_name,
        )
    if fail_count and not all_cues:
        # Inference itself failed — 90s window fallback would hit the same error.
        raise RuntimeError(
            f"Qwen3-ASR {label} failed {fail_count}/{len(frames)} frames "
            f"({media_name}): {_qwen_error_text(first_err)}"
        )
    if not all_cues:
        return None
    return _dedupe_overlap_cues(all_cues)


def _qwen_windowed_transcribe(
    *,
    media_path: str,
    model: Any,
    lang: str | None,
    duration_s: float,
    want_ts: bool,
    on_progress: ProgressCb | None,
    on_cue: CueCb | None,
    should_cancel: Callable[[], bool] | None,
) -> list[dict[str, Any]]:
    from ..audio.preprocess import stage_media_for_long_asr, touch_path, trim_media_window

    windows = _windows(duration_s)
    work = Path(tempfile.mkdtemp(prefix="qwen3_asr_"))
    all_cues: list[dict[str, Any]] = []
    fail_count = 0
    first_err: BaseException | None = None
    last_key = ""
    same_streak = 0
    try:
        staged = stage_media_for_long_asr(media_path, work)
        for i, (start, end) in enumerate(windows):
            if should_cancel and should_cancel():
                raise RuntimeError("cancelled")
            if on_progress:
                local = asr_local_from_timeline(
                    processed_s=start,
                    duration_s=duration_s,
                    start=12.0,
                    end=92.0,
                )
                detail = f"{format_mmss(start)} / {format_mmss(duration_s)} · Qwen3"
                on_progress(
                    {
                        "stage": "transcribe",
                        "percent": int(local),
                        "detail": detail,
                        "processedSec": float(start),
                        "mediaDurationSec": duration_s,
                    }
                )
            if i % 10 == 0:
                touch_path(staged)
            wav = trim_media_window(
                staged,
                start_sec=start,
                end_sec=end,
                out_dir=work / f"w{i:04d}",
            )
            try:
                result = _transcribe_wav(model, str(wav), lang, want_ts=want_ts)
            except Exception as err:
                fail_count += 1
                if first_err is None:
                    first_err = err
                key = str(err)[:240]
                same_streak = same_streak + 1 if key == last_key else 1
                last_key = key
                _log.warning("Qwen3-ASR window %s-%s failed: %s", start, end, err)
                if _qwen_fail_fast(err=err, first_err=first_err, same_streak=same_streak):
                    n_win = max(1, len(windows))
                    raise RuntimeError(
                        f"Qwen3-ASR failed {fail_count}/{n_win} windows "
                        f"({Path(media_path).name}): {_qwen_error_text(first_err)}"
                    ) from err
                continue
            span = max(0.1, end - start)
            if want_ts:
                part = _result_to_cues_aligned(result, offset_s=start, span_s=span)
            else:
                text = _result_text(result)
                part = (
                    _distribute_text_cues(text, start=start, end=start + span * 0.95)
                    if text
                    else []
                )
            for cue in part:
                if on_cue:
                    on_cue(cue)
                all_cues.append(cue)
    finally:
        shutil.rmtree(work, ignore_errors=True)

    n_win = max(1, len(windows))
    if fail_count and (fail_count >= (n_win + 1) // 2 or not all_cues):
        detail = _qwen_error_text(first_err) if first_err else "no cues"
        raise RuntimeError(
            f"Qwen3-ASR failed {fail_count}/{n_win} windows "
            f"({Path(media_path).name}): {detail}"
        )
    return _dedupe_overlap_cues(all_cues)


def qwen3_asr_transcribe(
    *,
    media_path: str,
    language: str = "auto",
    asr_model: str = "qwen3-asr-0.6b",
    device: str = "auto",
    timing_align_model: str | None = None,
    qwen_batch_mode: str | None = "auto",
    perf_profile: str | None = None,
    job_gpu_free_mib: int | None = None,
    job_gpu_total_mib: int | None = None,
    on_progress: ProgressCb | None = None,
    on_cue: CueCb | None = None,
    should_cancel: Callable[[], bool] | None = None,
) -> list[dict[str, Any]]:
    from ..runtime_extras import ensure_extras_for_models, ensure_numpy_numba_compatible

    # Emit BEFORE torch import — first CUDA load can take minutes with no other events.
    if on_progress:
        on_progress(
            {
                "stage": "model",
                "percent": 2,
                "detail": f"准备加载 {asr_model}（导入 Torch）…",
            }
        )

    # Prefer fixing numpy while native DLLs are still unlocked. Serve usually
    # does this before preload; keep a job-time pass for older engine processes.
    if on_progress:
        on_progress(
            {
                "stage": "model",
                "percent": 2,
                "detail": "检查 NumPy / Numba 兼容性…",
            }
        )
    fix_early = ensure_numpy_numba_compatible(on_progress=on_progress)
    if not fix_early.get("ok"):
        raise RuntimeError(
            "Numba needs NumPy <2.5; "
            f"auto-fix failed: {fix_early.get('message') or 'pip error'}"
        )

    from ..device import (
        format_torch_cuda_load_failure,
        is_torch_fully_imported,
        is_torch_reimport_poisoned,
        torch_reimport_poison_message,
    )

    if is_torch_reimport_poisoned():
        raise RuntimeError(torch_reimport_poison_message())

    # Serve may have preloaded torch (torch\\lib before nvidia inject). Skip costly probe.
    if is_torch_fully_imported():
        if on_progress:
            on_progress(
                {
                    "stage": "model",
                    "percent": 5,
                    "detail": "Torch 已就绪 · 检查运行依赖…",
                }
            )
    elif sys.platform == "win32":
        if on_progress:
            on_progress(
                {
                    "stage": "model",
                    "percent": 3,
                    "detail": "检测 Torch/CUDA（子进程）…",
                }
            )
        if not _probe_torch_cuda_import(timeout_sec=60.0):
            if on_progress:
                on_progress(
                    {
                        "stage": "model",
                        "percent": 4,
                        "detail": "子进程导入失败 · 尝试本进程预加载 Torch…",
                    }
                )
            try:
                from ..runtime_gpu import preload_torch_cuda_dlls

                pre = preload_torch_cuda_dlls()
                if not pre.get("ok"):
                    raise RuntimeError(
                        format_torch_cuda_load_failure(pre.get("message") or "")
                    )
            except RuntimeError:
                raise
            except Exception as err:
                raise RuntimeError(format_torch_cuda_load_failure(err)) from err

    # Windows: load torch before ensure_extras can further poison cuBLAS.
    try:
        _import_torch()
    except Exception as err:
        _log.warning("Qwen3-ASR: early torch import failed: %s", err)
        raise

    if on_progress:
        on_progress(
            {
                "stage": "model",
                "percent": 5,
                "detail": "Torch 已就绪 · 检查运行依赖…",
            }
        )

    use_aligner = wants_forced_aligner(timing_align_model)
    ensure_ids = [asr_model]
    if use_aligner:
        ensure_ids.append(_ALIGNER_ID)
    ensure_extras_for_models(
        ensure_ids,
        force=False,
        on_progress=on_progress,
    )
    # Repair numpy floated by unconstrained pip during extras install.
    fix = ensure_numpy_numba_compatible(on_progress=on_progress)
    if not fix.get("ok"):
        raise RuntimeError(
            "Numba needs NumPy <2.5; "
            f"auto-fix failed: {fix.get('message') or 'pip error'}"
        )
    if not is_model_installed(asr_model):
        raise RuntimeError(
            f"ASR model not installed: {asr_model}. "
            f"Download {asr_model} (or qwen3-asr-0.6b) first."
        )
    asr_dir = model_local_path(asr_model)
    aligner_dir: Path | None = None
    if use_aligner:
        try:
            if is_model_installed(_ALIGNER_ID):
                aligner_dir = model_local_path(_ALIGNER_ID)
            else:
                _log.warning(
                    "ForcedAligner requested but %s not installed; "
                    "falling back to VAD/window timing",
                    _ALIGNER_ID,
                )
                use_aligner = False
        except Exception:
            aligner_dir = None
            use_aligner = False

    if on_progress:
        mode = " + ForcedAligner…" if use_aligner and aligner_dir else "（VAD 帧时间戳）…"
        on_progress(
            {
                "stage": "model",
                "percent": 8,
                "detail": f"加载 Qwen3-ASR{mode}",
            }
        )
    # Resolve batch before loading weights — post-load mem_get_info under-estimates headroom.
    island_batch_n = resolve_island_batch_size(
        asr_model,
        batch_mode=qwen_batch_mode,
        device=device,
        perf_profile=perf_profile,
        job_gpu_free_mib=job_gpu_free_mib,
        job_gpu_total_mib=job_gpu_total_mib,
    )
    batch_label = _effective_batch_mode(qwen_batch_mode, perf_profile)
    vram_free, vram_total = _resolve_vram_mib(
        job_gpu_free_mib=job_gpu_free_mib,
        job_gpu_total_mib=job_gpu_total_mib,
    )
    _log.info(
        "Qwen3 island batch plan: model=%s mode=%s batch=%d device=%s vram_free=%s vram_total=%s",
        asr_model,
        batch_label,
        island_batch_n,
        device,
        vram_free,
        vram_total,
    )
    if on_progress:
        on_progress(
            {
                "stage": "model",
                "percent": 10,
                "detail": "加载 Qwen3-ASR 权重到设备（首次可能较久）…",
            }
        )
    model = _get_asr_model(asr_dir, aligner_dir if use_aligner else None, device)
    lang = _map_language(language)
    duration_s = _probe_duration_s(media_path)
    if duration_s <= 0:
        raise RuntimeError(
            f"无法读取媒体时长（{media_path}），Qwen3-ASR 不能安全开窗。"
            "请确认 ffmpeg/ffprobe 可用后重试。"
        )

    cleaned: list[dict[str, Any]] = []
    if use_aligner and aligner_dir is not None:
        cleaned = _qwen_windowed_transcribe(
            media_path=media_path,
            model=model,
            lang=lang,
            duration_s=duration_s,
            want_ts=True,
            on_progress=on_progress,
            on_cue=on_cue,
            should_cancel=should_cancel,
        )
    else:
        # Default + aligner-missing fallback: TEN/FireRed frames; empty timingAlign → windows.
        island_backend = _island_vad_backend(
            None if wants_forced_aligner(timing_align_model) else timing_align_model
        )
        if island_backend:
            if island_backend == "firered":
                ensure_extras_for_models(
                    ["firered-vad"],
                    force=False,
                    on_progress=on_progress,
                )
            vad_cues = _qwen_island_vad_transcribe(
                media_path=media_path,
                model=model,
                lang=lang,
                duration_s=duration_s,
                vad_backend=island_backend,
                device=device,
                asr_model=asr_model,
                qwen_batch_mode=qwen_batch_mode,
                perf_profile=perf_profile,
                job_gpu_free_mib=job_gpu_free_mib,
                job_gpu_total_mib=job_gpu_total_mib,
                island_batch_n=island_batch_n,
                on_progress=on_progress,
                on_cue=on_cue,
                should_cancel=should_cancel,
            )
            if vad_cues is not None:
                cleaned = vad_cues
            else:
                cleaned = _qwen_windowed_transcribe(
                    media_path=media_path,
                    model=model,
                    lang=lang,
                    duration_s=duration_s,
                    want_ts=False,
                    on_progress=on_progress,
                    on_cue=on_cue,
                    should_cancel=should_cancel,
                )
        else:
            cleaned = _qwen_windowed_transcribe(
                media_path=media_path,
                model=model,
                lang=lang,
                duration_s=duration_s,
                want_ts=False,
                on_progress=on_progress,
                on_cue=on_cue,
                should_cancel=should_cancel,
            )

    if on_progress:
        on_progress(
            {
                "stage": "transcribe",
                "percent": 96,
                "detail": f"{len(cleaned)} 条（Qwen3-ASR）",
                "processedSec": duration_s,
                "mediaDurationSec": duration_s,
            }
        )
    return cleaned
